html:
{% set company = frappe.db.get_default("company") or frappe.db.get_single_value("Global Defaults", "default_company") %}
{% set company_logo = frappe.db.get_value("Company", company, "company_logo") if company else "" %}
{% set company_name = company or "ASIA PETROCHEMICALS LLC" %}
{% set company_address = "Dubai - United Arab Emirates" %}
{% set company_web = "www.asia-petrochem.com" %}
{% set qty = frappe.db.get_value("APC Batch", doc.batch, "batch_quantity") if doc.batch else None %}

{% set inv_number = doc.inv_number or doc.invoice_number or doc.custom_inv_number or doc.get("inv_number") or doc.get("invoice_number") or doc.get("custom_inv_number") %}
{% set pi_number = doc.pi_number or doc.proforma_invoice_number or doc.custom_pi_number or doc.get("pi_number") or doc.get("proforma_invoice_number") or doc.get("custom_pi_number") %}

<style>
  @page {
    size: A4;
    margin: 8mm;
  }

  body {
    margin: 0;
    padding: 0;
    font-family: Arial, sans-serif;
    color: #000;
  }

  .coa-page {
    min-height: auto;
    border: 1.5px solid #222;
    padding: 4mm 8mm 3mm 8mm;
    box-sizing: border-box;
    font-family: Arial, sans-serif;
    color: #000;
    position: relative;
  }

  .coa-head {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 4px;
  }

  .coa-head td {
    vertical-align: top;
  }

  .coa-logo {
    width: 150px;
    text-align: left;
    padding-top: 2px;
  }

  .coa-logo img {
    width: 115px;
    height: 90px;
    object-fit: contain;
    display: block;
  }

  .coa-title-wrap {
    text-align: center;
    padding-top: 2px;
  }

  .coa-company {
    font-size: 22px;
    font-weight: 700;
    letter-spacing: 0.3px;
    text-transform: uppercase;
    line-height: 1.1;
  }

  .coa-sub {
    font-size: 14px;
    margin-top: 4px;
    line-height: 1.15;
  }

  .coa-main-title {
    text-align: center;
    font-size: 21px;
    font-weight: 700;
    margin: 8px 0 4px;
    letter-spacing: 0.3px;
    text-transform: uppercase;
  }

  .double-rule {
    border-top: 2px solid #000;
    border-bottom: 2px solid #000;
    height: 3px;
    margin: 4px 0 0;
  }

  .info-box {
    border-left: 1px solid #333;
    border-right: 1px solid #333;
    border-bottom: 1px solid #333;
    padding: 6px 20px 10px 20px;
    min-height: auto;
    box-sizing: border-box;
  }

  .cert-row {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 8px;
  }

  .cert-row td {
    font-size: 14px;
    font-weight: 700;
    padding: 4px 0;
  }

  .cert-row .right {
    text-align: right;
  }

  .details {
    width: 100%;
    border-collapse: collapse;
    margin-top: 8px;
  }

  .details td {
    padding: 3px 0;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.25;
    vertical-align: top;
  }

  .details .k {
    width: 130px;
  }

  .details .c {
    width: 18px;
    text-align: center;
  }

  .details .v {
    width: auto;
  }

  .consignee-line {
    display: flex;
    justify-content: space-between;
    gap: 18px;
    width: 100%;
  }

  .consignee-name {
    flex: 1;
  }

  .doc-refs {
    white-space: nowrap;
    text-align: right;
    font-size: 13px;
  }

  .doc-refs span {
    margin-left: 14px;
  }

  .section-rule {
    border-top: 2px solid #000;
    border-bottom: 2px solid #000;
    height: 3px;
    margin: 6px 0 6px;
  }

  .tests {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .tests th,
  .tests td {
    border: 1px solid #333;
    padding: 4px 6px;
    font-size: 13px;
    line-height: 1.2;
    vertical-align: middle;
  }

  .tests th {
    text-align: center;
    font-weight: 700;
    text-transform: uppercase;
  }

  .tests td {
    font-weight: 500;
  }

  .center {
    text-align: center;
  }

  .footer-rule {
    border-top: 2px solid #000;
    border-bottom: 2px solid #000;
    height: 3px;
    margin: 10px 0 8px;
  }

  .footer {
    width: 100%;
    border-collapse: collapse;
    margin-top: 8px;
  }

  .footer td {
    vertical-align: bottom;
    font-size: 13px;
  }

  .footer-left {
    width: 34%;
    text-align: center;
  }

  .footer-left img {
    width: 90px;
    height: 90px;
    object-fit: contain;
    opacity: 0.85;
  }

  .footer-company {
    margin-top: 8px;
    font-size: 15px;
    font-weight: 700;
  }

  .footer-mid,
  .footer-right {
    width: 22%;
    border-left: 1px solid #333;
    padding-left: 12px;
    line-height: 1.45;
  }

  .sign-wrap {
    width: 22%;
    text-align: center;
    padding-bottom: 4px;
  }

  .sign-title {
    font-size: 14px;
    font-weight: 700;
    margin-bottom: 16px;
  }

  .sign-sub {
    font-size: 13px;
    font-weight: 700;
  }

  @media print {
    .coa-page {
      page-break-after: avoid;
    }
  }
</style>

<div class="coa-page">

  <table class="coa-head">
    <tr>
      <td class="coa-logo">
        {% if company_logo %}
          <img src="{{ company_logo }}" alt="Company Logo">
        {% else %}
          <img src="/files/AP_Logo.webp" alt="Company Logo" onerror="this.style.display='none'">
        {% endif %}
      </td>

      <td class="coa-title-wrap">
        <div class="coa-company">{{ company_name }}</div>
        <div class="coa-sub">{{ company_address }}</div>
        <div class="coa-sub">Web: <u>{{ company_web }}</u></div>
        <div class="coa-main-title">CERTIFICATE OF ANALYSIS</div>
      </td>

      <td style="width:150px;"></td>
    </tr>
  </table>

  <div class="double-rule"></div>

  <div class="info-box">
    <table class="cert-row">
      <tr>
        <td></td>
        <td class="right">
          Certificate No: {{ doc.coa_number or doc.name }}
        </td>
      </tr>
      <tr>
        <td></td>
        <td class="right">
          Date: {{ frappe.utils.formatdate(doc.coa_date) if doc.coa_date else "-" }}
        </td>
      </tr>
    </table>

    <table class="details">
      <tr>
        <td class="k">Product Name</td>
        <td class="c">:</td>
        <td class="v">{{ doc.product_name or doc.product or "-" }}</td>
      </tr>

      <tr>
        <td class="k">Consignee</td>
        <td class="c">:</td>
        <td class="v">
          <div class="consignee-line">
            <div class="consignee-name">
              {{ doc.customer or "-" }}
            </div>
        </tr>
        <tr>
            <div class="doc-refs">
              {% if inv_number %}
                <span>INV No: {{ inv_number }}</span>
              {% endif %}
            </div>
        </tr>
        <tr>
            <div class="doc-refs">
              {% if pi_number %}
                <span>PI No: {{ pi_number }}</span>
              {% endif %}
             </div>
        </tr>
            </div>
          </div>
        </td>
      </tr>

      <tr>
        <td class="k">B.NO.</td>
        <td class="c">:</td>
        <td class="v">{{ doc.batch or doc.batch_number or "-" }}</td>
      </tr>

      <tr>
        <td class="k">Mfg. Date</td>
        <td class="c">:</td>
        <td class="v">{{ frappe.utils.formatdate(doc.manufacturing_date) if doc.manufacturing_date else "-" }}</td>
      </tr>

      <tr>
        <td class="k">Quantity</td>
        <td class="c">:</td>
        <td class="v">{{ qty if qty is not none else "-" }}</td>
      </tr>

      <tr>
        <td class="k">Approval Status</td>
        <td class="c">:</td>
        <td class="v">{{ doc.approval_status or doc.status or "-" }}</td>
      </tr>
    </table>
  </div>

  <div class="section-rule"></div>

  <table class="tests">
    <thead>
      <tr>
        <th style="width:27%;">TEST</th>
        <th style="width:15%;">METHOD</th>
        <th style="width:8%;">UNIT</th>
        <th style="width:27%;">SPECIFICATION</th>
        <th style="width:23%;">RESULT</th>
      </tr>
    </thead>

    <tbody>
      {% for row in (doc.test_results or []) %}

        {% set method_val = row.method or "-" %}

        {# Clean min/max values so default Float 0.00 does not print #}
        {% set raw_min = row.min_value %}
        {% set raw_max = row.max_value %}

        {% set min_text = "" %}
        {% set max_text = "" %}

        {% if raw_min not in (None, "", 0, 0.0, "0", "0.0", "0.00") %}
          {% set min_text = raw_min|string %}
        {% endif %}

        {% if raw_max not in (None, "", 0, 0.0, "0", "0.0", "0.00") %}
          {% set max_text = raw_max|string %}
        {% endif %}

        {# Specification priority:
           1. Use real min/max range if available
           2. Use only max if available
           3. Use only min if available
           4. Use the parameter's Specification text
           5. Print blank fallback
        #}
        {% if min_text and max_text %}
          {% set spec_val = min_text + " - " + max_text %}
        {% elif max_text %}
          {% set spec_val = "Max " + max_text %}
        {% elif min_text %}
          {% set spec_val = "Min " + min_text %}
        {% elif row.specification %}
          {% set spec_val = row.specification %}
        {% else %}
          {% set spec_val = "-" %}
        {% endif %}

        {% set result_val = row.text_result or row.result_value %}
        {% if row.value_type == "Numeric" and row.numeric_result not in (None, "") %}
          {% set result_val = row.numeric_result %}
        {% endif %}

        <tr>
          <td class="center">{{ row.parameter_name or row.parameter or "-" }}</td>
          <td class="center">{{ method_val }}</td>
          <td class="center">{{ row.uom or "-" }}</td>
          <td class="center">{{ spec_val }}</td>
          <td class="center">{{ result_val or "-" }}</td>
        </tr>

      {% else %}
        <tr>
          <td colspan="5" class="center">No test results found.</td>
        </tr>
      {% endfor %}
    </tbody>
  </table>

  <div class="footer-rule"></div>

  <table class="footer">
    <tr>
      <td class="footer-left">
        {% if company_logo %}
          <img src="{{ company_logo }}" alt="Company Seal">
        {% else %}
          <img src="/files/AP_Logo.webp" alt="Company Seal" onerror="this.style.display='none'">
        {% endif %}
        <div class="footer-company">{{ company_name }}</div>
      </td>

      <td class="footer-mid">
        <b>Corporate Office</b><br>
        PO Box 76283, Dubai, UAE<br>
        Tel: 04-2384533<br>
        Fax: 04-2384534
      </td>

      <td class="footer-right">
        <b>Manufacturing Plant</b><br>
        PO Box 85618, Ras Al Khaimah, UAE<br>
        Tel: 07-2276033<br>
        Fax: 07-2438005
      </td>

      <td class="sign-wrap">
        <div class="sign-title">Authorized Signatory</div>
        <div class="sign-sub">Laboratory Manager</div>
      </td>
    </tr>
  </table>

</div>
